import numpy as np

def wml(r, J, K, skip=0):
    T = r.shape[0]
    f = formation_returns(r, J, skip)
    W = np.zeros(r.shape)
    for s in range(J + skip, T):
        W[s] = cohort_weights(f[s])
    out = []
    for t in range(J + skip + K - 1, T):
        book = W[t - K + 1:t + 1].mean(axis=0)
        out.append(book @ r[t])
    return np.array(out)

def n_obs(T, J, K, skip, overlapping):
    if overlapping:
        return max(0, T - J - skip - K + 1)
    return max(0, (T - J - skip) // K)

