widget.solution:
import numpy as np

def composite_turnover(r, J, K):
    T = r.shape[0]
    f = formation_returns(r, J)
    W = np.zeros(r.shape)
    for s in range(J, T):
        W[s] = cohort_weights(f[s])
    books = np.array([W[t - K + 1:t + 1].mean(axis=0)
                      for t in range(J + K - 1, T)])
    traded = np.abs(np.diff(books, axis=0)).sum(axis=1)
    return float(np.mean(traded))
